  "claims": [
    {
      "claim": "In Svizzera, l'obbligo di assicurazione malattia (assicurazione di base o LAMal) si applica immediatamente a partire dal giorno in cui una persona si stabilisce in Svizzera o inizia a lavorare in Svizzera, indipendentemente dalla durata del soggiorno.",
      "verdict": "supported"
    },
    {
      "claim": "Non esiste un periodo di attesa di tre mesi prima di poter stipulare l'assicurazione obbligatoria.",
      "verdict": "contradicted"
    },
    {
      "claim": "Se una persona non contrae un'assicurazione malattia obbligatoria entro tre mesi dall'inizio dell'obbligo di assicurazione, viene automaticamente assegnata a un assicuratore malattia di sua scelta (o a uno designato dall'autorità cantonale).",
      "verdict": "supported"
    },
    {
      "claim": "In caso di ritardo volontario e senza giustificato motivo, l'assicurato potrebbe essere soggetto a sanzioni, come il pagamento di premi retroattivi maggiorati con interessi di mora.",
      "verdict": "supported"
    },
    {
      "claim": "È fondamentale stipulare l'assicurazione malattia obbligatoria non appena si risiede o si lavora in Svizzera per evitare problemi amministrativi e costi aggiuntivi.",
      "verdict": "supported"
    }
  ],
  "behavior_violation": false,
